import subprocess, os, tempfile, shutil, time, urllib.request, urllib.parse, urllib.error, sqlite3, json
EXE=os.path.abspath("executable")
class Drill:
    def __init__(self, tmp, port=18010, extra=None):
        self.tmp=tmp; self.port=port
        args=[EXE,"drill","--port",str(port),"--open-browser","false"]+(extra or [])+[tmp]
        self.proc=subprocess.Popen(args, stdout=subprocess.PIPE, stderr=subprocess.PIPE, text=True)
        # wait for server
        for i in range(50):
            time.sleep(0.1)
            if self.proc.poll() is not None:
                break
            try:
                self.req("/")
                break
            except Exception:
                continue
    def req(self, path, method="GET", data=None, raw=None, headers=None):
        url=f"http://127.0.0.1:{self.port}{path}"
        body=raw
        hd=dict(headers or {})
        if data is not None:
            body=urllib.parse.urlencode(data).encode(); hd['Content-Type']='application/x-www-form-urlencoded'
        rreq=urllib.request.Request(url, data=body, method=method, headers=hd)
        try:
            with urllib.request.urlopen(rreq, timeout=2) as r:
                return r.status, dict(r.headers), r.read()
        except urllib.error.HTTPError as e:
            return e.code, dict(e.headers), e.read()
    def get(self,p): return self.req(p)
    def post(self, data): return self.req("/", method="POST", data=data)
    def close(self):
        if self.proc.poll() is None:
            self.proc.terminate()
            try: return self.proc.communicate(timeout=3)
            except: self.proc.kill(); return ("","")
        else:
            return self.proc.communicate(timeout=3)
    def db(self):
        db=os.path.join(self.tmp,"hashcards.db")
        con=sqlite3.connect(db); cur=con.cursor()
        out={}
        for tbl in ["cards","sessions","reviews"]:
            try:
                cur.execute(f"SELECT * FROM {tbl}")
                out[tbl]=cur.fetchall()
            except Exception as e: out[tbl]=str(e)
        return out

