    tmp=tempfile.mkdtemp()
    for p,c in struct.items():
        fp=os.path.join(tmp,p); os.makedirs(os.path.dirname(fp),exist_ok=True)
        mode='wb' if isinstance(c,bytes) else 'w'
        with open(fp,mode) as f: f.write(c)
    return tmp
