def card_text(html):
    if "Session Completed" in html:
        m=re.search(r'<div class="summary">(.*?)</div>',html); return "FIN:"+ (m.group(1) if m else "")
    content=re.search(r'<div class="card-content">(.*?)</div></div></div><div class="controls">',html,re.S)
    txt=re.sub('<[^>]+>','|',content.group(1)).strip() if content else html[:200]
    progress=re.search(r'progress-fill" style="width: ([0-9]+)%',html).group(1)
    undo_disabled="id=\"undo\" type=\"submit\" name=\"action\" value=\"Undo\" disabled" in html
    buttons=re.findall(r'name="action" value="([^"]+)"',html)
    return f"progress={progress}% undo_disabled={undo_disabled} buttons={buttons} content={txt!r}"
def act(d, a):
    d.post({"action":a})
    s,h,b=d.get("/"); print(f"after {a}:", card_text(b.decode()))
tmp=make_tmp({"Deck.md":"Q: q1\nA: a1\n\nQ: q2\nA: a2\n\nQ: q3\nA: a3\n"})
d=Drill(tmp,19400)
s,h,b=d.get("/"); print("initial:", card_text(b.decode()))
for a in ["Undo","Good","Forgot","Reveal","Reveal","Undo","Good","Undo","Reveal","Good","Reveal","Hard","Undo","Undo","Reveal","Easy","End","Undo","Reveal","Good","Shutdown"]:
    # if process dead break
    if d.proc.poll() is not None: print("proc exited"); break
    try: act(d,a)
    except Exception as e: print("after",a,"err",e); break
print("db",d.db())
print("poll",d.proc.poll())
import time; time.sleep(.2); print("poll2",d.proc.poll())
try: print(d.close())
except Exception as e: print(e)
PY
python3 /tmp/drill_actions.py 2>&1 | tail -n 100"}

