import struct

_IV = [0x6A09E667, 0xBB67AE85, 0x3C6EF372, 0xA54FF53A,
       0x510E527F, 0x9B05688C, 0x1F83D9AB, 0x5BE0CD19]
_MSG_PERMUTATION = [2, 6, 3, 10, 7, 0, 4, 13, 1, 11, 12, 5, 9, 14, 15, 8]
_FLAG_CHUNK_START = 1 << 0
_FLAG_CHUNK_END = 1 << 1
_FLAG_PARENT = 1 << 2
_FLAG_ROOT = 1 << 3
_MASK = 0xFFFFFFFF


def _rotr(x, n):
    return ((x >> n) | ((x << (32 - n)) & _MASK)) & _MASK


def _g(v, a, b, c, d, x, y):
    v[a] = (v[a] + v[b] + x) & _MASK
    v[d] = _rotr(v[d] ^ v[a], 16)
    v[c] = (v[c] + v[d]) & _MASK
    v[b] = _rotr(v[b] ^ v[c], 12)
    v[a] = (v[a] + v[b] + y) & _MASK
    v[d] = _rotr(v[d] ^ v[a], 8)
    v[c] = (v[c] + v[d]) & _MASK
    v[b] = _rotr(v[b] ^ v[c], 7)


def _round(v, m):
    _g(v, 0, 4, 8, 12, m[0], m[1])
    _g(v, 1, 5, 9, 13, m[2], m[3])
    _g(v, 2, 6, 10, 14, m[4], m[5])
    _g(v, 3, 7, 11, 15, m[6], m[7])
    _g(v, 0, 5, 10, 15, m[8], m[9])
    _g(v, 1, 6, 11, 12, m[10], m[11])
    _g(v, 2, 7, 8, 13, m[12], m[13])
    _g(v, 3, 4, 9, 14, m[14], m[15])


def _permute(m):
    return [m[_MSG_PERMUTATION[i]] for i in range(16)]


def _compress(cv, block, counter, block_len, flags):
    block_words = list(struct.unpack('<16I', block))
    v = cv[:] + _IV[:4] + [counter & _MASK, (counter >> 32) & _MASK, block_len, flags]
    _round(v, block_words)
    for _ in range(6):
        block_words = _permute(block_words)
        _round(v, block_words)
    out = [0] * 16
    for i in range(8):
        out[i] = v[i] ^ v[i + 8]
        out[i + 8] = v[i + 8] ^ cv[i]
    return out


def _words_to_bytes(words):
    return struct.pack('<16I', *words)


class _Output:
    __slots__ = ('cv', 'block', 'counter', 'block_len', 'flags')

    def __init__(self, cv, block, counter, block_len, flags):
        self.cv = cv
        self.block = block
        self.counter = counter
        self.block_len = block_len
        self.flags = flags

    def chaining_value(self):
        return _compress(self.cv, self.block, self.counter, self.block_len, self.flags)[:8]

    def root_bytes(self, length):
        out = bytearray()
        counter = 0
        while len(out) < length:
            words = _compress(self.cv, self.block, counter, self.block_len, self.flags | _FLAG_ROOT)
            out += _words_to_bytes(words)
            counter += 1
        return bytes(out[:length])


def _chunk_output(data, counter=0):
    # data: up to 1024 bytes
    cv = _IV[:]
    if len(data) == 0:
        blocks = [(b'\x00' * 64, 0)]
    else:
        blocks = []
        for i in range(0, len(data), 64):
            chunk = data[i:i + 64]
            blocks.append((chunk.ljust(64, b'\x00'), len(chunk)))
    output = None
    for idx, (block, block_len) in enumerate(blocks):
        flags = 0
        if idx == 0:
            flags |= _FLAG_CHUNK_START
        if idx == len(blocks) - 1:
            flags |= _FLAG_CHUNK_END
            output = _Output(cv, block, counter, block_len, flags)
        else:
            out = _compress(cv, block, counter, block_len, flags)
            cv = out[:8]
    return output


def _parent_output(left_cv, right_cv, is_root_output=False):
    block_words = left_cv[:] + right_cv[:]
    block = _words_to_bytes(block_words)
    return _Output(_IV[:], block, 0, 64, _FLAG_PARENT)


def _parent_cv(left_cv, right_cv):
    return _parent_output(left_cv, right_cv).chaining_value()


def _largest_power_of_two_chunks_bytes(total_len):
    # Number of bytes in the largest power-of-two number of chunks
    # that is strictly less than total_len (when total_len > 1024).
    chunk_count = (total_len + 1023) // 1024
    power = 1
    while power * 2 < chunk_count:
        power *= 2
    # If chunk_count is itself a power of two, left subtree is half of it.
    # The loop above yields power < chunk_count, or power == chunk_count/2
    # when chunk_count is a power of two. Good.
    return power * 1024


def _subtree_output(data, chunk_counter=0):
    if len(data) <= 1024:
        return _chunk_output(data, chunk_counter)
    left_len = _largest_power_of_two_chunks_bytes(len(data))
    left_cv = _subtree_output(data[:left_len], chunk_counter).chaining_value()
    right_cv = _subtree_output(data[left_len:], chunk_counter + left_len // 1024).chaining_value()
    return _parent_output(left_cv, right_cv)


def blake3(data, out_len=32):
    if isinstance(data, str):
        data = data.encode()
    return _subtree_output(data, 0).root_bytes(out_len)


def blake3_hex(data):
    return blake3(data, 32).hex()
