                if lang:
                    html = '<pre><code class="language-%s">%s</code></pre>\n' % (escape_attr(lang), escape_text(content))
                else:
                    html = '<pre><code>%s</code></pre>\n' % escape_text(content)
                out_blocks.append(('code', html))
                i = j + 1 if j < n else j
                continue
