            hm = re.match(r'^ {0,3}(#{1,6})(?:[ \t]+|[ \t]*$)(.*)$', line)
            if hm:
                level = len(hm.group(1)); content = hm.group(2).strip()
                content = re.sub(r'[ \t]+#+[ \t]*$', '', content)
                if re.fullmatch(r'#+', content): content = ''
                out_blocks.append(('heading', '<h%d>%s</h%d>\n' % (level, self.render_inline(content), level)))
                i += 1; continue
            # thematic break
            if re.fullmatch(r' {0,3}([-*_])(?:[ \t]*\1){2,}[ \t]*', line):
                out_blocks.append(('hr', '<hr />\n')); i += 1; continue
            # html block
            hb = _html_block_start(line)
            if hb is not None:
                kind, tag = hb
                j = i; collected = []
                if kind == 'endtag':
                    while j < n:
                        collected.append(lines[j])
                        if ('</' + tag) in lines[j].lower(): j += 1; break
                        j += 1
                elif kind == 'comment':
                    while j < n:
                        collected.append(lines[j]); j += 1
                        if '-->' in collected[-1]: break
                elif kind == 'pi':
                    while j < n:
                        collected.append(lines[j]); j += 1
                        if '?>' in collected[-1]: break
                elif kind == 'decl':
                    while j < n:
                        collected.append(lines[j]); j += 1
                        if '>' in collected[-1]: break
                elif kind == 'cdata':
                    while j < n:
                        collected.append(lines[j]); j += 1
                        if ']]>' in collected[-1]: break
                else:
                    while j < n and lines[j].strip() != '':
                        collected.append(lines[j]); j += 1
                raw = '\n'.join(collected)
                if j < n: raw += '\n'
                out_blocks.append(('html', raw)); i = j; continue
            # blockquote
            if re.match(r'^ {0,3}>', line):
                inner = []; j = i
                while j < n:
                    l = lines[j]
                    qm = re.match(r'^ {0,3}> ?(.*)$', l)
                    if qm:
                        inner.append(qm.group(1)); j += 1; continue
                    if l.strip() == '':
                        break
