                out_blocks.append(('blockquote', '<blockquote>\n%s</blockquote>\n' % inner_html))
                i = j; continue
            # list
            lm = self._list_marker(line)
            if lm is not None:
                blocks, consumed = self._parse_list(lines, i)
                out_blocks.extend(blocks); i += consumed; continue
            # indented code (not interrupting paragraph; we are at block start)
            if line.startswith('    ') or line.startswith('\t'):
                j = i; code_lines = []
                while j < n and (lines[j].startswith('    ') or lines[j].startswith('\t') or lines[j].strip() == ''):
                    if lines[j].strip() == '':
                        code_lines.append(''); j += 1; continue
                    code_lines.append(lines[j][4:] if lines[j].startswith('    ') else lines[j][1:]); j += 1
                while code_lines and code_lines[-1] == '': code_lines.pop()
                content = ''.join(l + '\n' for l in code_lines)
                out_blocks.append(('code', '<pre><code>%s</code></pre>\n' % escape_text(content)))
                i = j; continue
            # paragraph / setext / table
            para_lines = []; j = i
            while j < n:
                l = lines[j]
                if l.strip() == '':
                    break
                if j > i:
                    # setext heading underline
                    if re.fullmatch(r' {0,3}=+[ \t]*', l):
                        content = '\n'.join(para_lines)
                        out_blocks.append(('heading', '<h1>%s</h1>\n' % self.render_inline(content.strip())))
                        para_lines = None; j += 1; break
                    if re.fullmatch(r' {0,3}-+[ \t]*', l):
                        content = '\n'.join(para_lines)
                        out_blocks.append(('heading', '<h2>%s</h2>\n' % self.render_inline(content.strip())))
                        para_lines = None; j += 1; break
                    # table delimiter as second line
                    if len(para_lines) == 1:
                        aligns = _is_table_delim(l)
                        if aligns is not None and '|' in (para_lines[0] + l):
                            # handled after loop via flag
                            para_lines.append(l); j += 1
