                    if re.match(r'^ {0,3}(#{1,6})(?:[ \t]+|$)', l) or re.match(r'^ {0,3}(`{3,}|~{3,})', l) or re.match(r'^ {0,3}>', l):
                        break
                    if re.fullmatch(r' {0,3}([-*_])(?:[ \t]*\1){2,}[ \t]*', l):
                        break
                    lm2 = self._list_marker(l)
                    if lm2 is not None:
                        # lists can interrupt a paragraph when they start
                        # with a non-empty item; bullet always, ordered only at 1
                        if lm2[3] == 'bullet' or lm2[4] == 1:
                            break
                para_lines.append(l); j += 1
            if para_lines is None:
                i = j; continue
            if para_lines:
                # reference definitions at the start of the block
                k = 0
                while k < len(para_lines):
                    r = _parse_ref_def_at(para_lines, k)
                    if r is None: break
                    label, dest, title, consumed = r
                    key = _normalize_label(label)
                    if key not in self.refs:
                        self.refs[key] = (dest, title)
                    # if this definition was already collected in the
                    # pre-pass, the refs are set; just consume.
                    k += max(1, consumed)
