                    # lines ending with two spaces: convert to backslash-newline marker
                    # Instead, post-process: inline parser handles '\\n' but
                    # not two-space breaks; transform here:
                    content2 = re.sub(r' {2,}\n', '\\\n', content)
                    if tight_list:
                        out_blocks.append(('paragraph', self.render_inline(content2) + '\n'))
                    else:
                        out_blocks.append(('paragraph', '<p>%s</p>\n' % self.render_inline(content2)))
                i = j; continue
            i = j if j > i else i + 1
        return out_blocks

    def _render_table(self, header_line, aligns, body_lines):
        headers = _split_table_row(header_line)
        ncol = len(aligns)
        headers = (headers + [''] * ncol)[:ncol]
        def cell(tag, idx, txt):
            a = aligns[idx]
            style = ' style="text-align: %s"' % a if a else ''
            return '<%s%s>%s</%s>' % (tag, style, self.render_inline(txt), tag)
        out = ['<table><thead><tr>']
        for idx, h in enumerate(headers): out.append(cell('th', idx, h))
        out.append('</tr></thead><tbody>\n')
        for row in body_lines:
            cells = _split_table_row(row)
            cells = (cells + [''] * ncol)[:ncol]
            out.append('<tr>')
            for idx, c in enumerate(cells): out.append(cell('td', idx, c))
            out.append('</tr>\n')
        out.append('</tbody></table>\n')
        return ''.join(out)

    def _list_marker(self, line):
        m = re.match(r'^( *)([-+*])([ \t]+|$)', line)
        if m:
            indent = len(m.group(1))
            if indent > 3: return None
            after = m.group(3)
            return (indent, m.group(2), after, 'bullet', None)
        m = re.match(r'^( *)(\d{1,9})([.)])([ \t]+|$)', line)
        if m:
            indent = len(m.group(1))
            if indent > 3: return None
            return (indent, m.group(3), m.group(4), 'ordered', int(m.group(2)))
        return None

    def _parse_list(self, lines, start):
        first = self._list_marker(lines[start])
        base_indent, marker_char, _after, kind, start_num = first
        items = []
        i = start; n = len(lines)
        loose = False
        while i < n:
            lm = self._list_marker(lines[i])
            if lm is None or lm[0] != base_indent or lm[3] != kind:
                break
            if kind == 'bullet' and lm[1] != marker_char:
                break
            if kind == 'ordered' and lm[1] != marker_char:
                break
