            m = re.match(r'^ *([-*+]|\d{1,9}[.)])([ \t]*)', lines[i])
            marker_width = len(m.group(1))
            spaces = len(m.group(2))
            if spaces >= 5:
                content_indent = base_indent + marker_width + 1
            else:
                content_indent = base_indent + marker_width + spaces if spaces > 0 else base_indent + marker_width + 1
            first_content = lines[i][content_indent:] if len(lines[i]) >= content_indent else ''
            item_lines = [first_content]
            # check if first content is blank
            j = i + 1
            item_loose_blank = False
            while j < n:
                l = lines[j]
                if l.strip() == '':
                    # lookahead
                    if j + 1 < n:
                        nxt = lines[j + 1]
                        lm_next = self._list_marker(nxt)
                        if lm_next is not None and lm_next[0] == base_indent and lm_next[3] == kind and (kind != 'bullet' or lm_next[1] == marker_char) and (kind != 'ordered' or lm_next[1] == marker_char):
                            item_lines.append(''); item_loose_blank = True; j += 1; break
                        if len(nxt) >= content_indent and (nxt.startswith(' ' * content_indent) or nxt.startswith('\t')):
                            item_lines.append(''); item_loose_blank = True; j += 1; continue
                    # trailing blank
                    j += 1; break
                lm2 = self._list_marker(l)
                if lm2 is not None and lm2[0] == base_indent and lm2[3] == kind and (kind != 'bullet' or lm2[1] == marker_char) and (kind != 'ordered' or lm2[1] == marker_char):
                    break
                if len(l) >= content_indent and l[:content_indent].strip() == '':
                    item_lines.append(l[content_indent:]); j += 1; continue
                # lazy continuation
                if item_lines and item_lines[-1].strip() != '':
                    item_lines.append(l); j += 1; continue
                break
            # strip trailing blank lines of item
            while item_lines and item_lines[-1] == '':
                item_lines.pop()
            if item_loose_blank:
                loose = True
            # blank line between items also makes loose; detect blank consumed
            items.append(item_lines)
            i = j
            # if we stopped because of blank separation, next iteration will parse next item
            # detect loose by a blank line separating items
            # (item_loose_blank already covers most)
        # A list is loose if any item had an internal blank line followed by more content
        # Re-evaluate: internal blank in any item (not just before next item)
        for it in items:
            if '' in it:
                loose = True
        if kind == 'bullet':
