                open_tag = '<ol>\n'
            else:
                open_tag = '<ol start="%d">\n' % start_num
            close_tag = '</ol>\n'
        html = [open_tag]
        for item_lines in items:
            if not item_lines or all(l.strip() == '' for l in item_lines):
                html.append('<li></li>\n'); continue
            blocks = self.parse_lines(item_lines, tight_list=not loose)
            if not blocks:
                html.append('<li></li>\n'); continue
            first_kind = blocks[0][0]
            body = ''.join(h for _, h in blocks)
            if not loose and first_kind == 'paragraph':
                # body already ends with \n from paragraph fragment
                if body.endswith('\n'):
                    body = body[:-1]
                html.append('<li>%s</li>\n' % body)
            else:
                html.append('<li>\n%s</li>\n' % body)
        html.append(close_tag)
        return [('list', ''.join(html))], i - start


def render_markdown(text, media_resolver=None, media_sink=None):
    if text == '':
        return ''
    refs = collect_references(text)
    parser = _BlockParser(refs, media_resolver=media_resolver, media_sink=media_sink)
    blocks = parser.parse(text)
    return ''.join(h for _, h in blocks)
