"""A small Markdown renderer modelled on the observable output of the
pulldown-cmark based renderer used by the original program.

Only the CommonMark features enabled there (plus tables and math) are
implemented.  The output conventions (tag spelling, attribute order,
trailing newlines, escaping) follow the observed HTML.
"""
import re
import html as _html_module
from urllib.parse import unquote

# ----------------------------------------------------------------- escaping

def escape_text(s):
    return s.replace('&', '&amp;').replace('<', '&lt;').replace('>', '&gt;')


def escape_attr(s):
    return (s.replace('&', '&amp;').replace('<', '&lt;').replace('>', '&gt;')
             .replace('"', '&quot;').replace("'", '&#39;'))


_HREF_SAFE = set("ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-._~:/?#[]@!$&()*+,;=%")

def escape_href(s):
    out = []
    for b in s.encode('utf-8'):
        ch = chr(b)
        if b < 33 or b >= 127 or ch in '"\'<>`\\^{}|':
            out.append('%%%02X' % b)
        else:
            out.append(ch)
    return ''.join(out)


def escape_url_segment(seg):
    # url crate path-segment percent-encode set: encode everything except
    # unreserved / sub-delims / ':' / '@' (roughly), observed &, +, = kept.
    safe = set("ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-._~!$&'()*+,;=:@")
    out = []
    for b in seg.encode('utf-8'):
        ch = chr(b)
        if ch in safe:
            out.append(ch)
        else:
            out.append('%%%02X' % b)
    return ''.join(out)


_NAMED_ENTITIES = _html_module.entities.html5

def decode_entities(s):
    # CommonMark entity references require a terminating semicolon.
    def repl(m):
        body = m.group(1)
        if body.startswith('#'):
            try:
                if body[1:2] in ('x', 'X'):
                    cp = int(body[2:], 16)
                else:
                    cp = int(body[1:], 10)
            except ValueError:
                return m.group(0)
            if cp == 0 or cp > 0x10FFFF or 0xD800 <= cp <= 0xDFFF:
                return '\ufffd'
            return chr(cp)
        val = _NAMED_ENTITIES.get(body + ';')
        if val is None:
            return m.group(0)
        return val
    return re.sub(r'&(#(?:[xX][0-9A-Fa-f]{1,6}|[0-9]{1,7})|[A-Za-z][A-Za-z0-9]{1,31});', repl, s)


def percent_decode(s):
    raw = unquote(s, errors='replace')
    return raw

# ----------------------------------------------------------------- references

def _normalize_label(label):
    return ' '.join(label.split()).casefold()


# ----------------------------------------------------------------- inline

class _InlineParser:
    def __init__(self, text, refs, ctx=None):
