        def flush():
            if buf:
                nodes.append(('text', decode_entities(''.join(buf))))
                buf.clear()
        while i < end:
            c = s[i]
            if stop_bracket and c == ']' :
                break
            # backslash escapes / hard break
            if c == '\\':
                if i + 1 < end and s[i + 1] == '\n':
                    flush(); nodes.append(('hardbreak',)); i += 2; continue
                if i + 1 < end and s[i + 1] in '!"#$%&\'()*+,-./:;<=>?@[\\]^_`{|}~':
                    buf.append(s[i + 1]); i += 2; continue
                buf.append('\\'); i += 1; continue
            # code span
            if c == '`':
                j = i
                while j < end and s[j] == '`':
                    j += 1
                run = j - i
                # find closing run
                k = j; closing = -1
                while k < end:
                    if s[k] == '`':
                        l = k
                        while l < end and s[l] == '`':
                            l += 1
                        if l - k == run:
                            closing = k; close_end = l; break
                        k = l
                    else:
                        k += 1
                if closing >= 0:
                    flush()
                    content = s[j:closing].replace('\n', ' ')
                    if len(content) >= 2 and content[0] == ' ' and content[-1] == ' ' and content.strip(' ') != '':
                        content = content[1:-1]
                    nodes.append(('code', content)); i = close_end; continue
                buf.append(s[i:j]); i = j; continue
            # math
            if c == '$':
                r = self._try_math(i)
                if r is not None:
                    flush(); nodes.append(('math', r[0], r[1])); i = r[2]; continue
                # emit a single literal dollar and move past one char;
                # if it was $$, the second will be considered next round.
                buf.append('$'); i += 1; continue
            # raw html / autolink
            if c == '<':
                parsed = self._parse_angle(i, end)
                if parsed is not None:
                    kind = parsed[0]
                    if kind == 'html':
                        flush(); nodes.append(('html', parsed[1])); i = parsed[2]; continue
                    if kind == 'autolink':
                        flush(); nodes.append(('autolink', parsed[1], parsed[2])); i = parsed[3]; continue
                buf.append('<'); i += 1; continue
            # images / links
            if c == '!' and i + 1 < end and s[i + 1] == '[':
                r = self._try_link(i + 1, end, image=True)
                if r is not None:
                    flush(); nodes.append(r[0]); i = r[1]; continue
                buf.append('!'); i += 1; continue
            if c == '[' and not in_link:
                r = self._try_link(i, end, image=False)
                if r is not None:
                    flush(); nodes.append(r[0]); i = r[1]; continue
                buf.append('['); i += 1; continue
            # emphasis delimiters are handled in a post-process over
            # the raw token stream; for simplicity we treat * and _
            # runs here by recursive parsing.
            if c in '*_':
                r = self._try_emphasis(i, end, in_link)
                if r is not None:
                    flush(); nodes.append(r[0]); i = r[1]; continue
                buf.append(c); i += 1; continue
            buf.append(c); i += 1
        flush()
        return nodes

    def _parse_angle(self, i, end):
        s = self.text
        # comments / declarations / PI / CDATA
        for opener, closer in [('<!--', '-->'), ('<?', '?>'), ('<![CDATA[', ']]>')]:
            if s.startswith(opener, i):
                j = s.find(closer, i + len(opener), end)
                if j >= 0:
                    return ('html', s[i:j + len(closer)], j + len(closer))
        if s.startswith('<!', i) and i + 2 < end and s[i + 2].isalpha():
            j = s.find('>', i + 2, end)
            if j >= 0:
                return ('html', s[i:j + 1], j + 1)
        m = re.match(r'</?[A-Za-z][A-Za-z0-9-]*(?:\s+(?:[^<>\'"=]+(?:\s*=\s*(?:[^\s"\'=<>`]+|"[^"]*"|\'[^\']*\'))?)*)?\s*/?>', s[i:end])
        if m:
            return ('html', m.group(0), i + m.end())
        # autolink
        m = re.match(r'<([A-Za-z][A-Za-z0-9+.-]{1,31}:[^<>\s]*)>', s[i:end])
        if m:
            uri = decode_entities(m.group(1))
            return ('autolink', uri, uri, i + m.end())
        m = re.match(r'<([A-Za-z0-9.!#$%&\'*+/=?^_`{|}~-]+@[A-Za-z0-9](?:[A-Za-z0-9-]{0,61}[A-Za-z0-9])?(?:\.[A-Za-z0-9](?:[A-Za-z0-9-]{0,61}[A-Za-z0-9])?)*)>', s[i:end])
        if m:
            email = decode_entities(m.group(1))
            return ('autolink', 'mailto:' + email, email, i + m.end())
        return None

    # -------- emphasis (simplified delimiter matching)
    def _try_emphasis(self, i, end, in_link):
        s = self.text
        ch = s[i]
        j = i
        while j < end and s[j] == ch:
            j += 1
        run = j - i
        # Find a matching closer.  We attempt runs of the same char,
        # preferring the nearest usable closer.  Content is parsed
        # recursively so nested emphasis / math / code work.
        # Rules approximated: opener cannot be followed by whitespace;
        # closer cannot be preceded by whitespace; '_' cannot open/close
        # intraword.
        if j < end and s[j].isspace():
            return None
        if ch == '_' and i > 0 and (s[i - 1].isalnum()):
            # left-flanking issues; allow only if not intraword for opening
            # opening '_' inside a word is not emphasis
            if j < end and s[j].isalnum():
                return None
        k = j
        while k < end:
            if s[k] == '\\':
                k += 2; continue
            if s[k] == '`':
                # skip code span
                l = k
                while l < end and s[l] == '`': l += 1
                runlen = l - k
                close = s.find('`' * runlen, l, end)
                k = close + runlen if close >= 0 else l
                continue
            if s[k] == ch:
                l = k
                while l < end and s[l] == ch:
                    l += 1
                closer_run = l - k
                if k > j and not s[k - 1].isspace():
                    if ch == '_' and l < end and s[l].isalnum() and s[k - 1].isalnum():
                        k = l; continue
                    # choose how many to use: strong if both >=2
                    inner_text = s[j:k]
                    if run >= 2 and closer_run >= 2:
                        children = _InlineParser(inner_text, self.refs, self.ctx)._parse_with_media(self.media_refs)
                        return (('strong', children), l - (closer_run - 2) if False else k + 2)
                    else:
                        children = _InlineParser(inner_text, self.refs, self.ctx)._parse_with_media(self.media_refs)
                        return (('emph', children), k + 1)
                k = l; continue
            k += 1
        return None

    def _parse_with_media(self, media_sink):
        nodes = self.parse()
        media_sink.extend(self.media_refs)
        return nodes

    # -------- links / images
    def _find_bracket_close(self, i, end):
        s = self.text
        depth = 0
        j = i
        while j < end:
            c = s[j]
            if c == '\\':
                j += 2; continue
            if c == '`':
                l = j
                while l < end and s[l] == '`': l += 1
                run = l - j
                close = s.find('`' * run, l, end)
                j = close + run if close >= 0 else l
                continue
            if c == '[':
                depth += 1
            elif c == ']':
                depth -= 1
                if depth == 0:
                    return j
            j += 1
        return -1

    def _try_link(self, i, end, image=False):
        s = self.text
        close = self._find_bracket_close(i, end)
        if close < 0:
            return None
        text_inside = s[i + 1:close]
        pos = close + 1
        dest = None; title = None; ref_label = None
        inline_dest = False
        if pos < end and s[pos] == '(':
            parsed = self._parse_link_destination(pos, end)
            if parsed is None:
                return None
            dest, title, pos = parsed; inline_dest = True
        elif pos < end and s[pos] == '[':
            close2 = s.find(']', pos + 1, end)
            if close2 < 0:
                return None
            label = s[pos + 1:close2]
            ref_label = label if label != '' else text_inside
            pos = close2 + 1
        else:
            ref_label = text_inside
        if not inline_dest:
            key = _normalize_label(ref_label or '')
            entry = self.refs.get(key)
            if entry is None:
                return None
            dest, title = entry
        # children
        sub = _InlineParser(text_inside, self.refs, self.ctx)
        children = sub.parse()
        self.media_refs.extend(sub.media_refs)
        if image:
            self.media_refs.append(percent_decode(dest or ''))
            node = ('image', dest or '', title, children)
        else:
            node = ('link', dest or '', title, children)
        return (node, pos)

    def _parse_link_destination(self, pos, end):
        s = self.text
        i = pos + 1
        while i < end and s[i] in ' \t\n':
            i += 1
        if i >= end:
            return None
        dest = ''
        if i < end and s[i] == '<':
            j = i + 1
            buf = []
            while j < end and s[j] != '>':
                if s[j] == '\\' and j + 1 < end:
                    buf.append(s[j + 1]); j += 2; continue
                if s[j] == '\n':
                    return None
                buf.append(s[j]); j += 1
            if j >= end:
                return None
            dest = ''.join(buf); i = j + 1
        else:
            depth = 0; buf = []
            while i < end:
                c = s[i]
                if c == '\\' and i + 1 < end and s[i + 1] in '!"#$%&\'()*+,-./:;<=>?@[\\]^_`{|}~':
                    buf.append(s[i + 1]); i += 2; continue
                if c == '(':
                    depth += 1; buf.append(c); i += 1; continue
                if c == ')':
                    if depth == 0:
                        break
                    depth -= 1; buf.append(c); i += 1; continue
                if c in ' \t\n' and depth == 0:
                    break
                if ord(c) < 0x20:
                    break
                buf.append(c); i += 1
            dest = ''.join(buf)
        dest = decode_entities(dest)
        # optional title
        while i < end and s[i] in ' \t\n':
            i += 1
        title = None
        if i < end and s[i] in ('"', "'"):
            q = s[i]; j = i + 1; buf = []
            while j < end and s[j] != q:
                if s[j] == '\\' and j + 1 < end:
                    buf.append(s[j + 1]); j += 2; continue
                buf.append(s[j]); j += 1
            if j >= end:
                return None
            title = decode_entities(''.join(buf)); i = j + 1
            while i < end and s[i] in ' \t\n':
                i += 1
        elif i < end and s[i] == '(':
            j = i + 1; buf = []
            while j < end and s[j] != ')':
                if s[j] == '\\' and j + 1 < end:
                    buf.append(s[j + 1]); j += 2; continue
                buf.append(s[j]); j += 1
            if j >= end:
                return None
            title = decode_entities(''.join(buf)); i = j + 1
            while i < end and s[i] in ' \t\n':
                i += 1
        if i < end and s[i] == ')':
            return (dest, title, i + 1)
        return None


# ----------------------------------------------------------------- node -> HTML

def _plain_text(nodes):
    out = []
    for n in nodes:
        k = n[0]
        if k == 'text': out.append(n[1])
        elif k == 'code': out.append(n[1])
        elif k == 'math': out.append('$' + n[2] + '$' if n[1] == 'inline' else '$$' + n[2] + '$$')
        elif k == 'html': out.append(n[1])
        elif k == 'hardbreak': out.append('\n')
        elif k in ('emph', 'strong'): out.append(_plain_text(n[1]))
        elif k in ('link', 'image'): out.append(_plain_text(n[3]))
        elif k == 'autolink': out.append(n[2])
    return ''.join(out)


def _render_nodes(nodes, renderer):
    out = []
    for n in nodes:
        k = n[0]
        if k == 'text':
            out.append(escape_text(n[1]))
        elif k == 'html':
            out.append(n[1])
        elif k == 'code':
            out.append('<code>' + escape_text(n[1]) + '</code>')
        elif k == 'hardbreak':
            out.append('<br />\n')
        elif k == 'math':
            cls = 'math math-inline' if n[1] == 'inline' else 'math math-display'
            out.append('<span class="%s">%s</span>' % (cls, escape_text(n[2])))
        elif k == 'emph':
            out.append('<em>' + _render_nodes(n[1], renderer) + '</em>')
        elif k == 'strong':
            out.append('<strong>' + _render_nodes(n[1], renderer) + '</strong>')
        elif k == 'autolink':
            out.append('<a href="%s">%s</a>' % (escape_attr(escape_href(n[1])), escape_text(n[2])))
        elif k == 'link':
            dest, title, children = n[1], n[2], n[3]
            href = escape_attr(escape_href(dest))
            if title is not None:
                out.append('<a href="%s" title="%s">%s</a>' % (href, escape_attr(title), _render_nodes(children, renderer)))
            else:
                out.append('<a href="%s">%s</a>' % (href, _render_nodes(children, renderer)))
        elif k == 'image':
            dest, title, children = n[1], n[2], n[3]
            out.append(renderer.render_image(dest, title, children))
    return ''.join(out)


class _Renderer:
    def __init__(self, media_resolver=None):
        # media_resolver: fn(decoded_dest) -> url string or None
        self.media_resolver = media_resolver

    def render_image(self, dest, title, children):
        decoded = percent_decode(dest or '')
        url = None
        if self.media_resolver is not None:
            url = self.media_resolver(decoded, dest or '')
        if url is None:
            url = escape_href(dest or '')
            src_attr = escape_attr(url)
        else:
            src_attr = escape_attr(url)
        # audio check uses the decoded destination extension, case sensitive
        base = decoded.split('/')[-1]
        ext = base.rsplit('.', 1)[-1] if '.' in base else ''
        if ext in ('mp3', 'wav', 'ogg'):
            t = title if title is not None else ''
            # NOTE: children are rendered as ordinary content *after* the
            # audio element (mirroring the observed behaviour).
            return '<audio controls src="%s" title="%s"></audio>%s' % (src_attr, escape_attr(t), _render_nodes(children, self))
        alt = escape_attr(_plain_text(children))
        if title is not None:
            return '<img src="%s" alt="%s" title="%s" />' % (src_attr, alt, escape_attr(title))
        return '<img src="%s" alt="%s" />' % (src_attr, alt)


def render_inline(text, refs=None, media_resolver=None, media_sink=None):
    parser = _InlineParser(text, refs or {}, None)
    nodes = parser.parse()
    if media_sink is not None:
        media_sink.extend(parser.media_refs)
    renderer = _Renderer(media_resolver)
    return _render_nodes(nodes, renderer)


def extract_media(text):
    """Return decoded image destinations found in a markdown fragment."""
    parser = _InlineParser(text, {}, None)
    # We need references too: first collect refs from the fragment itself.
    refs = collect_references(text)
    parser = _InlineParser(text, refs, None)
    parser.parse()
    return parser.media_refs

# ----------------------------------------------------------------- blocks

_REF_DEF_RE = re.compile(r' {0,3}\[([^\]]+)\]:[ \t]*(?:\n[ \t]*)?(<[^>\n]*>|\S+)?[ \t]*(?:\n[ \t]*)?(?:"([^"]*)"|\'([^\']*)\'|\(([^)]*)\))?[ \t]*(?:\n|$)')

def _parse_ref_def_at(lines, i):
    # Try to parse a link reference definition starting at lines[i].
    # Returns (label, dest, title, lines_consumed) or None.
    text = '\n'.join(lines[i:i + 3])
    m = re.match(r' {0,3}\[([^\]^][^\]]*)\]:[ \t]*', text)
    if not m:
        # footnote-style label is just a label for our purposes
        m = re.match(r' {0,3}\[([^\]]+)\]:[ \t]*', text)
        if not m:
            return None
    label = m.group(1)
    rest = text[m.end():]
    # destination on same or next line
    rest_stripped = rest.lstrip(' \t\n')
    if rest_stripped.startswith('<'):
        end = rest_stripped.find('>')
        if end < 0: return None
        dest = rest_stripped[1:end]
        after = rest_stripped[end + 1:]
    else:
        mm = re.match(r'[^\s]+', rest_stripped)
        if not mm:
            return None
        dest = mm.group(0); after = rest_stripped[mm.end():]
    consumed_text_len = len(text) - len(after) + (len(rest) - len(rest.lstrip(' \t\n')) if False else 0)
    # Simplify consumed lines: count newlines in the matched prefix up to dest end
    # Recompute by scanning the original joined text.
    # Title may follow.
    after_lstrip = after.lstrip(' \t')
    # title needs whitespace separation unless on next line
    title = None
    title_end_index = None
    a = after
    # skip spaces/newline at most...
    idx = 0
    while idx < len(a) and a[idx] in ' \t\n': idx += 1
    if idx < len(a) and a[idx] in ('"', "'", '('):
        q = a[idx]; closer = ')' if q == '(' else q
        endq = a.find(closer, idx + 1)
        if endq >= 0:
            # ensure remainder up to end of line is only spaces
            after_title = a[endq + 1:]
            line_end = after_title.find('\n')
            remainder = after_title if line_end < 0 else after_title[:line_end]
            if remainder.strip(' \t') == '':
                title = a[idx + 1:endq]
                total_consumed_chars = (len(text) - len(a)) + endq + 1
                lines_consumed = text[:total_consumed_chars].count('\n') + 1
                return (label, decode_entities(dest), decode_entities(title) if title is not None else None, lines_consumed)
    # no title; definition ends at the end of the line containing dest
    # find dest end position in text
    dest_pos = text.find(dest) if dest else -1
    # count lines up to the newline after dest
    upto = text[:]
    # The consumed area is up to (and including) the first newline after
    # the destination, or 1 line if none.
    search_from = m.end()
    nl = text.find('\n', search_from)
    # ensure only whitespace between dest end and newline
    if nl >= 0:
        between = text[search_from:nl]
        # between should be dest (+ spaces)
        if between.strip().split()[0:1] == [dest] or dest in between:
            lines_consumed = 1 + text[:nl].count('\n') if False else (text[:search_from].count('\n') + 1)
            # Actually the line containing dest may be the second line.
            lines_consumed = text[:nl].count('\n') + (1 if text[:search_from].count('\n') == text[:nl].count('\n') else 0)
            # Simpler: number of lines spanned = count of \n before nl +1 relative to start
            lines_consumed = text[:nl].count('\n') - '\n'.join(lines[:i]).count('\n') if False else None
            # We started joining at i, so local line count:
            lines_consumed = text[:nl].count('\n') + 1
            return (label, decode_entities(dest), None, lines_consumed)
    else:
        return (label, decode_entities(dest), None, 1)
    return None


def collect_references(text):
    refs = {}
    lines = text.split('\n')
    i = 0
    # A light-weight scan: definitions at line starts (allowing > / list prefixes roughly)
    in_fence = False; fence_char = None; fence_len = 0
    while i < len(lines):
        line = lines[i]
        stripped = line.strip()
        fm = re.match(r' {0,3}(`{3,}|~{3,})', line)
        if fm:
            if not in_fence:
                in_fence = True; fence_char = fm.group(1)[0]; fence_len = len(fm.group(1))
            elif line.strip().startswith(fence_char * fence_len):
                in_fence = False
            i += 1; continue
        if in_fence:
            i += 1; continue
        # strip blockquote / list container prefixes for detection
        probe = line
        for _ in range(3):
            probe2 = re.sub(r'^ {0,3}> ? ', '', probe)
            if probe2 == probe: break
            probe = probe2
        r = _parse_ref_def_at([probe] + lines[i + 1:], 0)
        if r is not None:
            label, dest, title, consumed = r
            key = _normalize_label(label)
            if key not in refs:
                refs[key] = (dest, title)
            i += max(1, consumed)
            continue
        i += 1
    return refs


def _split_table_row(row):
    row = row.strip()
    if row.startswith('|'):
        row = row[1:]
    if row.endswith('|') and not row.endswith('\\|'):
        row = row[:-1]
    cells = []
    buf = []; i = 0
    while i < len(row):
        c = row[i]
        if c == '\\' and i + 1 < len(row) and row[i + 1] == '|':
            buf.append('|'); i += 2; continue
        if c == '|':
            cells.append(''.join(buf).strip()); buf = []; i += 1; continue
        buf.append(c); i += 1
    cells.append(''.join(buf).strip())
    return cells


def _is_table_delim(line):
    cells = _split_table_row(line)
    if not cells:
        return None
    aligns = []
    for c in cells:
        if not re.fullmatch(r':?-{1,}:?', c.strip()):
            return None
        c = c.strip()
        if c.startswith(':') and c.endswith(':'): aligns.append('center')
        elif c.endswith(':'): aligns.append('right')
        elif c.startswith(':'): aligns.append('left')
        else: aligns.append(None)
    return aligns


_BLOCK_TAGS = set('address article aside base basefont blockquote body caption center col colgroup dd details dialog dir div dl dt fieldset figcaption figure footer form frame frameset h1 h2 h3 h4 h5 h6 head header hr html iframe legend li link main menu menuitem nav noframes ol optgroup option p param search section summary table tbody td tfoot th thead title tr track ul'.split())

def _html_block_start(line):
    s = line.lstrip()
    if len(line) - len(s) > 3:
        return None
    low = s.lower()
    for tag in ('pre', 'script', 'style', 'textarea'):
        if re.match(r'<%s(?=[\s>]|$)' % tag, low):
            return ('endtag', tag)
    if s.startswith('<!--'): return ('comment', None)
    if s.startswith('<?'): return ('pi', None)
    if re.match(r'<![A-Z]', s): return ('decl', None)
    if s.startswith('<![CDATA['): return ('cdata', None)
    m = re.match(r'</?([A-Za-z][A-Za-z0-9-]*)(?:\s|>|/>|$)', s)
    if m and m.group(1).lower() in _BLOCK_TAGS:
        return ('blank', None)
    # type 7: complete tag alone
    if m:
        return ('blank7', None)
    return None


class _BlockParser:
    def __init__(self, refs, media_resolver=None, media_sink=None):
        self.refs = refs
        self.media_resolver = media_resolver
        self.media_sink = media_sink

    def render_inline(self, text):
        return render_inline(text, self.refs, self.media_resolver, self.media_sink)

    def parse(self, text, tight_list=False):
        lines = text.split('\n')
        return self.parse_lines(lines, tight_list=tight_list)

    def parse_lines(self, lines, tight_list=False):
        out_blocks = []  # list of (kind, html)
        i = 0; n = len(lines)
        while i < n:
            line = lines[i]
            if line.strip() == '':
                i += 1; continue
            # fenced code
            fm = re.match(r'^( {0,3})(`{3,}|~{3,})(.*)$', line)
            if fm and not (fm.group(2)[0] == '`' and '`' in fm.group(3)):
                indent = len(fm.group(1)); fence = fm.group(2); info = fm.group(3).strip()
                ch = fence[0]; flen = len(fence)
                j = i + 1; code_lines = []
                while j < n:
                    cm = re.match(r'^ {0,3}(%s{%d,})[ \t]*$' % (re.escape(ch), flen), lines[j])
                    if cm: break
                    code_lines.append(lines[j]); j += 1
