        return [('list', ''.join(html))], i - start


def render_markdown(text, media_resolver=None, media_sink=None):
    if text == '':
        return ''
    refs = collect_references(text)
    parser = _BlockParser(refs, media_resolver=media_resolver, media_sink=media_sink)
    blocks = parser.parse(text)
    return ''.join(h for _, h in blocks)
