            self.err(self.pos, "expected `}`")


def parse_frontmatter_name(text):
    """Return the deck name string or None.  Raise TomlError."""
    parser = _Parser(text)
    root = parser.parse()
    if 'name' not in root:
        return None
    value = root['name']
    if isinstance(value, str):
        return value
    vstart, vend, _ = parser.value_spans.get('name', (0, 1, None))
    line, col, src = parser.line_col(vstart)
    if isinstance(value, bool):
        msg = "invalid type: boolean `%s`, expected a string" % ('true' if value else 'false')
    elif isinstance(value, int):
        msg = "invalid type: integer `%d`, expected a string" % value
    elif isinstance(value, float):
        msg = "invalid type: floating point `%s`, expected a string" % (repr(value))
    elif isinstance(value, list):
        msg = "invalid type: sequence, expected a string"
    else:
        msg = "invalid type: map, expected a string"
    raise TomlError(line, col, vend - vstart, msg, src)
