import os, struct
from .textutil import rust_trim, rust_lines
from .blake3 import blake3
from .toml_front import parse_frontmatter_name, TomlError
from .errors import AppError, SimpleError, err_io_from_oserror, err_io_utf8

class ParseError(AppError):
    def __init__(self, message, file_path, line):
        super().__init__(message)
        self.message = message; self.file_path = file_path; self.line = line
    def __str__(self):
        return "Parse error: %s Location: %s:%d" % (self.message, self.file_path, self.line)

class Card:
    __slots__ = ('hash', 'family_hash', 'deck_name', 'file_path', 'file_path_display', 'line_start', 'line_end', 'content', 'performance')
    def __init__(self, hash_, family, deck_name, file_path, display, ls, le, content):
        self.hash = hash_; self.family_hash = family; self.deck_name = deck_name
        self.file_path = file_path; self.file_path_display = display
        self.line_start = ls; self.line_end = le; self.content = content
        self.performance = None

def _stem_and_ext(name_bytes):
    # Return (stem_bytes or None, ext_bytes or None) following Rust Path rules.
    name = name_bytes
    if name in (b'.', b'..'):
        return (name, None)
    # find last dot
    if name.startswith(b'.'):
        rest = name[1:]
        if b'.' not in rest:
            return (name, None)
        idx = name.rfind(b'.')
        return (name[:idx], name[idx + 1:])
    else:
        if b'.' not in name:
            return (name, None)
        idx = name.rfind(b'.')
        return (name[:idx], name[idx + 1:])

def compute_hash_basic(question, answer):
    return blake3(b'Basic' + question.encode('utf-8') + answer.encode('utf-8')).hex()

def compute_hash_cloze(text, start, end):
    data = b'Cloze' + text.encode('utf-8') + struct.pack('<Q', start % (1 << 64)) + struct.pack('<Q', end % (1 << 64))
    return blake3(data).hex()

def compute_family_hash(text):
    return blake3(b'Cloze' + text.encode('utf-8')).hex()

def _parse_cloze_text(raw_text, file_display, start_line):
    text = raw_text
    out = []
    ranges = []
    in_cloze = False
    start = 0
    out_len = 0  # bytes
    i = 0
