import os
from .cards import parse_deck_text, read_text_file, load_macros, Card, _stem_and_ext
from .errors import SimpleError, err_io_from_oserror
from . import markdown as md

class Collection:
    def __init__(self, root_fs):
        self.root_fs = root_fs
        self.root_display = _lossy_path(root_fs)
        self.macros = []
        self.cards_by_hash = {}
        self.cards_sorted = []

    @property
    def cards(self):
        return self.cards_sorted

def _lossy_path(p):
    return os.fsencode(p).decode('utf-8', 'replace')

def canonicalize_root(arg):
    # arg: str (may contain surrogates). Returns fs path string.
    try:
        canon = os.path.realpath(arg)
    except Exception:
        raise SimpleError("directory does not exist.")
    # Rust fs::canonicalize errors if the path does not exist.
    if not os.path.lexists(arg):
        raise SimpleError("directory does not exist.")
    # os.path.realpath does not fail for missing paths; emulate via lexists on
    # the argument as passed (Rust canonicalize resolves components and any
    # missing component is an error).
    if not _all_components_exist(arg):
        raise SimpleError("directory does not exist.")
    return canon

def _all_components_exist(arg):
    # realpath already resolved as much as possible; if the canonical result
    # does not exist, the original path was missing something.
    return os.path.lexists(os.path.realpath(arg))

class _TraversalError(SimpleError):
    pass

def _traversal_error(path_fs, depth, e):
    from .errors import rust_dbg_str, ERRNO_KIND
    errno = e.errno or 0
    kind = ERRNO_KIND.get(errno, 'Uncategorized')
    msg = e.strerror or str(e)
    text = ('directory traversal error: Error {\n    depth: %d,\n    inner: Io {\n        path: Some(\n            %s,\n        ),\n        err: Os {\n            code: %d,\n            kind: %s,\n            message: %s,\n        },\n    },\n}' %
            (depth, rust_dbg_str(_lossy_path(path_fs)), errno, kind, rust_dbg_str(msg)))
    return SimpleError(text)

def load_collection(root_fs, db):
    coll = Collection(root_fs)
    coll.macros = load_macros(root_fs)
    _walk(root_fs, root_fs, 0, coll)
    coll.cards_sorted = [coll.cards_by_hash[h] for h in sorted(coll.cards_by_hash.keys())]
    _check_media(coll)
    return coll

def _walk(dir_fs, root_fs, depth, coll):
    try:
        entries = list(os.scandir(dir_fs))
    except OSError as e:
        raise _traversal_error(dir_fs, depth, e)
    for entry in entries:
        path = entry.path
        try:
            is_dir = entry.is_dir(follow_symlinks=False)
        except OSError:
            is_dir = False
        if is_dir:
            _walk(path, root_fs, depth + 1, coll)
            continue
        # regular file (following symlinks) with .md extension
        name_b = os.fsencode(os.path.basename(path))
        stem_b, ext_b = _stem_and_ext(name_b)
        if ext_b != b'md':
            continue
        if not os.path.isfile(path):
            continue
        _process_file(path, root_fs, coll)

def _process_file(entry_path, root_fs, coll):
    try:
        canon = os.path.realpath(entry_path)
    except Exception:
        raise SimpleError("Strip prefix error: StripPrefixError(\n    (),\n)")
    root_canon = os.path.realpath(root_fs)
    if not (canon == root_canon or canon.startswith(root_canon + os.sep)):
        raise SimpleError("Strip prefix error: StripPrefixError(\n    (),\n)")
    text = read_text_file(canon)
    name_b = os.fsencode(os.path.basename(canon))
    stem_b, ext_b = _stem_and_ext(name_b)
    try:
        deck_name = stem_b.decode('utf-8')
    except UnicodeDecodeError:
        deck_name = "None"
    display = _lossy_path(canon)
    new_cards = parse_deck_text(text, canon, display, deck_name)
    for c in new_cards:
        if c.hash not in coll.cards_by_hash:
            coll.cards_by_hash[c.hash] = c

def resolve_media_path(coll, card, dest):
    if dest == '':
        return None
    if dest.startswith('@/'):
        raw = os.path.join(coll.root_fs, dest[2:])
    else:
        raw = os.path.join(os.path.dirname(card.file_path), dest)
    if not os.path.exists(raw):
        return None
    canon = os.path.realpath(raw)
    root_canon = os.path.realpath(coll.root_fs)
    if canon == root_canon:
        return None
    if not canon.startswith(root_canon + os.sep):
        return None
    return canon

def _check_media(coll):
    missing = set()
    for card in coll.cards_by_hash.values():
        refs = []
        if 'basic' in card.content:
            refs.extend(md.extract_media(card.content['basic']['question']))
            refs.extend(md.extract_media(card.content['basic']['answer']))
        else:
            refs.extend(md.extract_media(card.content['cloze']['text']))
        for dest in refs:
            if resolve_media_path(coll, card, dest) is None:
                missing.add((dest, card.file_path_display, card.line_start))
    if missing:
        lines = ["Missing media files referenced in cards:"]
        for dest, path, line in sorted(missing):
            lines.append("  - %s (referenced in %s:%d)" % (dest, path, line))
        # Original message ends with a trailing blank line.
        raise SimpleError('\n'.join(lines) + "\n")
