    def bind(self):
        host = self.cfg['host']; port = self.cfg['port']
        infos = []
        try:
            infos = socket.getaddrinfo(host, port, 0, socket.SOCK_STREAM)
        except socket.gaierror as e:
            raise err_io_custom_uncategorized("failed to lookup address information: Temporary failure in name resolution")
        except Exception as e:
            raise err_io_custom_uncategorized("failed to lookup address information: Temporary failure in name resolution")
        seen = set(); last_err = None
        for family, stype, proto, canon, sockaddr in infos:
            key = (family, sockaddr)
            if key in seen: continue
            seen.add(key)
            s = socket.socket(family, stype, proto)
            try:
                s.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
                if family == socket.AF_INET6:
                    try: s.setsockopt(socket.IPPROTO_IPV6, socket.IPV6_V6ONLY, 1)
                    except Exception: pass
                s.bind(sockaddr); s.listen(128)
                self.listener = s; return
            except OSError as e:
                last_err = e; s.close(); continue
        if last_err is not None:
            raise err_io_from_oserror(last_err)
        raise err_io_custom_uncategorized("failed to lookup address information: Temporary failure in name resolution")

    # ----- routing
    def route(self, method, raw_path, query, body, headers):
        # method: str; raw_path percent-encoded, no query
        if raw_path == '/':
            if method not in ('GET', 'HEAD', 'POST'):
                return _Response(405, [('allow', 'GET,HEAD,POST')], b'')
            if method in ('GET', 'HEAD'):
                return _Response(200, [('content-type', 'text/html; charset=utf-8')], self.session.render_root())
            # POST
            return self._handle_post(body, headers)
        if raw_path in ('/style.css', '/script.js', '/katex/katex.css', '/katex/katex.js', '/katex/mhchem.js'):
            if method not in ('GET', 'HEAD'):
                return _Response(405, [('allow', 'GET,HEAD')], b'')
            return self._static_asset(raw_path)
        if raw_path.startswith('/katex/fonts/') and len(raw_path) > len('/katex/fonts/'):
            if method not in ('GET', 'HEAD'):
                return _Response(405, [('allow', 'GET,HEAD')], b'')
