            body = (macros_js + "\n" + script_js_tail()).encode('utf-8')
            return _Response(200, [('content-type', 'text/javascript')], body)
        if path == '/katex/katex.css':
            return _Response(200, [('content-type', 'text/css'), ('cache-control', 'public, max-age=604800, immutable')], load_asset('katex/katex.css') or b'')
        if path == '/katex/katex.js':
            return _Response(200, [('content-type', 'text/javascript'), ('cache-control', 'public, max-age=604800, immutable')], load_asset('katex/katex.js') or b'')
        if path == '/katex/mhchem.js':
            return _Response(200, [('content-type', 'text/javascript'), ('cache-control', 'public, max-age=604800, immutable')], load_asset('katex/mhchem.js') or b'')
        return _Response(404, [('content-type', 'text/html; charset=utf-8')], b'Not Found')

    def _serve_file(self, capture):
        if capture.startswith('/') or capture == '':
            return _Response(404, [('content-type', 'text/plain')], b'Not Found')
        parts = capture.split('/')
        if any(p == '..' for p in parts):
            return _Response(404, [('content-type', 'text/plain')], b'Not Found')
        fs_path = os.path.join(self.coll.root_fs, capture)
        try:
            st = os.lstat(fs_path)
        except OSError:
            return _Response(404, [('content-type', 'text/plain')], b'Not Found')
        import stat as _stat
        if not _stat.S_ISREG(st.st_mode):
            return _Response(404, [('content-type', 'text/plain')], b'Not Found')
        try:
            with open(fs_path, 'rb') as f:
                data = f.read()
        except OSError:
            return _Response(404, [('content-type', 'text/plain')], b'Not Found')
