GRADES = ('Forgot', 'Hard', 'Good', 'Easy')
ACTIONS = ('Reveal', 'Undo', 'End', 'Forgot', 'Hard', 'Good', 'Easy', 'Shutdown')

def _escape_deck(s):
    return s.replace('&', '&amp;').replace('<', '&lt;').replace('>', '&gt;').replace('"', '&quot;')

def _rust_path_ext(name):
    # name is a plain string path segment / file name
    base = name.rsplit('/', 1)[-1]
    if base.startswith('.') and '.' not in base[1:]:
        return None
    if '.' not in base:
        return None
    return base.rsplit('.', 1)[-1]

class SessionCard:
    __slots__ = ('card', 'perf')
    def __init__(self, card):
        self.card = card; self.perf = card.performance

class Review:
    __slots__ = ('scard', 'grade', 'reviewed_at', 'perf_after', 'perf_before')
    def __init__(self, scard, grade, at, after, before):
        self.scard = scard; self.grade = grade; self.reviewed_at = at
        self.perf_after = after; self.perf_before = before

class DrillSession:
    def __init__(self, coll, db, cfg, queue_cards, started_at):
        self.coll = coll; self.db = db; self.cfg = cfg
        self.started_at = started_at
        self.ended_at = None
        self.queue = [SessionCard(c) for c in queue_cards]
        self.total = len(self.queue)
        self.history = []
        self.revealed = False
        self.finished = False
        self.lock = threading.Lock()

    @property
    def completed(self):
        # cards no longer in the queue have graduated
        cards_in_queue = set(id(c) for c in self.queue)
        return self.total - len(cards_in_queue)

    @property
    def cards_reviewed(self):
        return self.completed

    def current(self):
        return self.queue[0] if self.queue else None

    def do_action(self, action):
        with self.lock:
            return self._do_action(action)

    def _do_action(self, action):
        if action == 'Reveal':
            if self.queue:
                self.revealed = True
            return False
        if action in GRADES:
            if not self.queue or not self.revealed:
                return False
            scard = self.queue.pop(0)
            before = scard.perf
            at = now_local()
            after = compute_performance(before, action, at)
            scard.perf = after
            self.history.append(Review(scard, action, at, after, before))
            if action in ('Forgot', 'Hard'):
                self.queue.append(scard)
            self.revealed = False
            if not self.queue:
                self._finish()
            return False
        if action == 'Undo':
            if not self.history:
                return False
            rec = self.history.pop()
            scard = rec.scard
            # remove from the queue if it is queued (re-queued or current)
            self.queue = [c for c in self.queue if c is not scard]
            self.queue.insert(0, scard)
            scard.perf = rec.perf_before
            self.revealed = False
            self.finished = False
            return False
        if action == 'End':
            self._finish()
            return False
        if action == 'Shutdown':
            return bool(self.finished)
        return False

    def _finish(self):
        self.finished = True
        self.ended_at = now_local()
        reviews = []
        card_perfs = {}
        for rec in self.history:
            reviews.append({'hash': rec.scard.card.hash, 'reviewed_at': rec.reviewed_at, 'grade': rec.grade, 'perf': rec.perf_after})
            if rec.scard.perf is not None:
                card_perfs[rec.scard.card.hash] = rec.scard.perf
        self.db.save_session(str(self.started_at), str(self.ended_at), reviews, card_perfs)

    # ------------- rendering
    def media_resolver_for(self, card):
        cfg_port = self.cfg['port']
        root = self.coll.root_fs
        def resolver(decoded, raw):
            canon = resolve_media_path(self.coll, card, decoded)
            if canon is None:
                return None
            rel = canon[len(os.path.realpath(root)):].lstrip('/')
            segs = rel.split('/') if rel else []
            url = 'http://localhost:%d/file/' % cfg_port + '/'.join(md.escape_url_segment(s) for s in segs)
            return url
        return resolver

    def render_card_html(self):
        scard = self.current()
        card = scard.card
        resolver = self.media_resolver_for(card)
        if 'basic' in card.content:
            q = md.render_markdown(card.content['basic']['question'], media_resolver=resolver)
            a = md.render_markdown(card.content['basic']['answer'], media_resolver=resolver) if self.revealed else ''
            content = '<div class="question rich-text">%s</div><div class="answer rich-text">%s</div>' % (q, a if self.revealed else '')
        else:
            content = '<div class="prompt rich-text">%s</div>' % self._render_cloze(card, resolver)
        undo = '<input id="undo" type="submit" name="action" value="Undo" disabled>' if not self.history else '<input id="undo" type="submit" name="action" value="Undo" title="Undo last action. Shortcut: u.">'
        if not self.revealed:
            controls_mid = '<input id="reveal" type="submit" name="action" value="Reveal" title="Show the answer. Shortcut: space.">'
        else:
            if self.cfg['answer_controls'] == 'binary':
                controls_mid = ('<div class="grades">'
                    '<input id="forgot" type="submit" name="action" value="Forgot" title="Mark card as forgotten.">'
                    '<input id="good" type="submit" name="action" value="Good" title="Mark card as remembered.">'
                    '</div>')
            else:
                controls_mid = ('<div class="grades">'
                    '<input id="forgot" type="submit" name="action" value="Forgot" title="Mark card as forgotten. Shortcut: 1.">'
                    '<input id="hard" type="submit" name="action" value="Hard" title="Mark card as difficult. Shortcut: 2.">'
                    '<input id="good" type="submit" name="action" value="Good" title="Mark card as remembered well. Shortcut: 3.">'
                    '<input id="easy" type="submit" name="action" value="Easy" title="Mark card as very easy. Shortcut: 4.">'
                    '</div>')
        progress = (self.completed * 100) // self.total if self.total else 0
        body = ('<div class="root"><div class="header"><div class="progress-bar"><div class="progress-fill" style="width: %d%%;"></div></div></div>'
                '<div class="card-container"><div class="card"><div class="card-header"><h1>%s</h1></div>'
                '<div class="card-content">%s</div></div></div>'
                '<div class="controls"><form action="/" method="post">%s<div class="spacer"></div>%s<div class="spacer"></div>'
                '<input id="end" type="submit" name="action" value="End" title="End the session (changes are saved)"></form></div></div>'
                % (progress, _escape_deck(card.deck_name), content, undo, controls_mid))
        return _page(body)

    def _render_cloze(self, card, resolver):
        text = card.content['cloze']['text']; start = card.content['cloze']['start']; end = card.content['cloze']['end']
        tb = text.encode('utf-8')
        after_start = (end + 1) % (1 << 64)
        before = tb[:start].decode('utf-8', 'replace')
        if self.revealed:
            deleted = tb[start:after_start].decode('utf-8', 'replace') if after_start >= start else ''
            if start == 0 and after_start == 0 and end >= (1 << 63):
                deleted = ''
            after = tb[after_start:].decode('utf-8', 'replace')
            spliced = before + "<span class='cloze-reveal'>" + deleted + "</span>" + after
        else:
            after = tb[after_start:].decode('utf-8', 'replace')
            spliced = before + "<span class='cloze'>.............</span>" + after
        return md.render_markdown(spliced, media_resolver=resolver)

    def render_finished_html(self):
        ended = self.ended_at or now_local()
        dur_ms = _timestamp_total_ms(ended) - _timestamp_total_ms(self.started_at)
        duration = int(dur_ms / 1000) if dur_ms >= 0 else -int((-dur_ms) / 1000)
        reviewed = self.cards_reviewed
        pace = (duration / reviewed) if reviewed else 0.0
        stats = [
            ('Total Cards', str(self.total)),
            ('Cards Reviewed', str(reviewed)),
            ('Started', self.started_at.format_display()),
            ('Finished', ended.format_display()),
            ('Duration (seconds)', str(duration)),
            ('Pace (s/card)', '%.2f' % pace),
        ]
        rows = ''.join('<tr><td class="key">%s</td><td class="val">%s</td></tr>' % (k, v) for k, v in stats)
        body = ('<div class="finished"><h1>Session Completed 🎉</h1>'
                '<div class="summary">Reviewed %d cards in %d seconds.</div>'
                '<h2>Session Stats</h2><div class="stats"><table><tbody>%s</tbody></table></div>'
                '<div class="shutdown-container"><form action="/" method="post">'
                '<input class="shutdown-button" id="shutdown" type="submit" name="action" value="Shutdown" title="Shut down the server">'
                '</form></div></div>' % (reviewed, duration, rows))
        return _page(body)

    def render_root(self):
        with self.lock:
            if self.finished:
                return self.render_finished_html()
            if not self.queue:
                return self.render_finished_html()
            return self.render_card_html()

def _timestamp_total_ms(ts):
    from .dates import days_from_civil
    days = days_from_civil(ts.y, ts.mo, ts.d)
    return (((days * 24 + ts.h) * 60 + ts.mi) * 60 + ts.s) * 1000 + ts.ms

