_FILE_MIME = {
    'png': 'image/png', 'jpg': 'image/jpeg', 'jpeg': 'image/jpeg', 'gif': 'image/gif',
    'svg': 'image/svg+xml', 'mp3': 'audio/mpeg', 'wav': 'audio/wav', 'ogg': 'audio/ogg',
    'mp4': 'video/mp4', 'webm': 'video/webm',
}

_STATUS_REASONS = {200: 'OK', 303: 'See Other', 400: 'Bad Request', 404: 'Not Found', 405: 'Method Not Allowed', 415: 'Unsupported Media Type', 422: 'Unprocessable Entity', 500: 'Internal Server Error'}

class _Response:
    __slots__ = ('status', 'headers', 'body', 'shutdown')
    def __init__(self, status, headers, body, shutdown=False):
        self.status = status; self.headers = headers; self.body = body; self.shutdown = shutdown

class DrillServer:
    def __init__(self, session, coll, cfg):
        self.session = session; self.coll = coll; self.cfg = cfg
        self.shutdown_requested = False
        self.listener = None

    def bind(self):
        host = self.cfg['host']; port = self.cfg['port']
        infos = []
        try:
            infos = socket.getaddrinfo(host, port, 0, socket.SOCK_STREAM)
        except socket.gaierror as e:
            raise err_io_custom_uncategorized("failed to lookup address information: Temporary failure in name resolution")
        except Exception as e:
            raise err_io_custom_uncategorized("failed to lookup address information: Temporary failure in name resolution")
        seen = set(); last_err = None
        for family, stype, proto, canon, sockaddr in infos:
            key = (family, sockaddr)
            if key in seen: continue
            seen.add(key)
            s = socket.socket(family, stype, proto)
            try:
                s.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
                if family == socket.AF_INET6:
                    try: s.setsockopt(socket.IPPROTO_IPV6, socket.IPV6_V6ONLY, 1)
                    except Exception: pass
                s.bind(sockaddr); s.listen(128)
                self.listener = s; return
            except OSError as e:
                last_err = e; s.close(); continue
        if last_err is not None:
            raise err_io_from_oserror(last_err)
        raise err_io_custom_uncategorized("failed to lookup address information: Temporary failure in name resolution")

    # ----- routing
    def route(self, method, raw_path, query, body, headers):
        # method: str; raw_path percent-encoded, no query
        if raw_path == '/':
            if method not in ('GET', 'HEAD', 'POST'):
                return _Response(405, [('allow', 'GET,HEAD,POST')], b'')
            if method in ('GET', 'HEAD'):
                return _Response(200, [('content-type', 'text/html; charset=utf-8')], self.session.render_root())
            # POST
            return self._handle_post(body, headers)
        if raw_path in ('/style.css', '/script.js', '/katex/katex.css', '/katex/katex.js', '/katex/mhchem.js'):
            if method not in ('GET', 'HEAD'):
                return _Response(405, [('allow', 'GET,HEAD')], b'')
            return self._static_asset(raw_path)
        if raw_path.startswith('/katex/fonts/') and len(raw_path) > len('/katex/fonts/'):
            if method not in ('GET', 'HEAD'):
                return _Response(405, [('allow', 'GET,HEAD')], b'')
            capture = unquote(raw_path[len('/katex/fonts/'):])
            data = font_asset(capture)
            if data is None:
                return _Response(404, [('content-type', 'text/plain'), ('cache-control', 'no-cache')], b'Not Found')
            return _Response(200, [('content-type', 'font/woff2'), ('cache-control', 'public, max-age=604800, immutable')], data)
        if raw_path.startswith('/file/') and len(raw_path) > len('/file/'):
            if method not in ('GET', 'HEAD'):
                return _Response(405, [('allow', 'GET,HEAD')], b'')
            capture = unquote(raw_path[len('/file/'):])
            return self._serve_file(capture)
        return _Response(404, [('content-type', 'text/html; charset=utf-8')], b'Not Found')

    def _static_asset(self, path):
        if path == '/style.css':
            return _Response(200, [('content-type', 'text/css'), ('cache-control', 'public, max-age=604800, immutable')], load_asset('style.css') or b'')
        if path == '/script.js':
            macros_js = "let MACROS = {};\n"
            for name, definition in self.coll.macros:
                macros_js += "MACROS['%s'] = '%s';\n" % (name, definition)
            body = (macros_js + "\n" + script_js_tail()).encode('utf-8')
            return _Response(200, [('content-type', 'text/javascript')], body)
        if path == '/katex/katex.css':
            return _Response(200, [('content-type', 'text/css'), ('cache-control', 'public, max-age=604800, immutable')], load_asset('katex/katex.css') or b'')
        if path == '/katex/katex.js':
            return _Response(200, [('content-type', 'text/javascript'), ('cache-control', 'public, max-age=604800, immutable')], load_asset('katex/katex.js') or b'')
        if path == '/katex/mhchem.js':
            return _Response(200, [('content-type', 'text/javascript'), ('cache-control', 'public, max-age=604800, immutable')], load_asset('katex/mhchem.js') or b'')
        return _Response(404, [('content-type', 'text/html; charset=utf-8')], b'Not Found')

    def _serve_file(self, capture):
        if capture.startswith('/') or capture == '':
            return _Response(404, [('content-type', 'text/plain')], b'Not Found')
        parts = capture.split('/')
        if any(p == '..' for p in parts):
            return _Response(404, [('content-type', 'text/plain')], b'Not Found')
        fs_path = os.path.join(self.coll.root_fs, capture)
        try:
            st = os.lstat(fs_path)
        except OSError:
            return _Response(404, [('content-type', 'text/plain')], b'Not Found')
        import stat as _stat
        if not _stat.S_ISREG(st.st_mode):
            return _Response(404, [('content-type', 'text/plain')], b'Not Found')
        try:
            with open(fs_path, 'rb') as f:
                data = f.read()
        except OSError:
            return _Response(404, [('content-type', 'text/plain')], b'Not Found')
        ext = _rust_path_ext(capture)
        mime = _FILE_MIME.get(ext.lower() if ext else '', 'application/octet-stream')
        return _Response(200, [('content-type', mime)], data)

    def _handle_post(self, body, headers):
        ctype = headers.get('content-type', '')
        # axum Form: requires application/x-www-form-urlencoded (parameters allowed)
        essence = ctype.split(';', 1)[0].strip()
        if essence != 'application/x-www-form-urlencoded':
            return _Response(415, [('content-type', 'text/plain; charset=utf-8')], b'Form requests must have `Content-Type: application/x-www-form-urlencoded`')
        text = body.decode('utf-8', 'replace')
        fields = []
        for pair in text.split('&'):
            if pair == '': continue
            if '=' in pair:
                k, v = pair.split('=', 1)
            else:
                k, v = pair, ''
            fields.append((_form_decode(k), _form_decode(v)))
        actions = [v for k, v in fields if k == 'action']
        if len(actions) == 0:
            return _Response(422, [('content-type', 'text/plain; charset=utf-8')], b'Failed to deserialize form body: missing field `action`')
        if len(actions) > 1:
            return _Response(422, [('content-type', 'text/plain; charset=utf-8')], b'Failed to deserialize form body: duplicate field `action`')
        action = actions[0]
        if action not in ACTIONS:
            msg = 'Failed to deserialize form body: action: unknown variant `%s`, expected one of `Reveal`, `Undo`, `End`, `Forgot`, `Hard`, `Good`, `Easy`, `Shutdown`' % action
            return _Response(422, [('content-type', 'text/plain; charset=utf-8')], msg.encode('utf-8'))
        shutdown = self.session.do_action(action)
        return _Response(303, [('location', '/')], b'', shutdown=shutdown)

    # ----- serving loop
    def serve(self):
        self.listener.settimeout(0.2)
        while not self.shutdown_requested:
            try:
                conn, _addr = self.listener.accept()
            except socket.timeout:
                continue
            except OSError:
                break
            t = threading.Thread(target=self._handle_conn, args=(conn,), daemon=True)
            t.start()
        try: self.listener.close()
        except Exception: pass

    def _handle_conn(self, conn):
        try:
            conn.settimeout(30)
            f = conn.makefile('rb')
            while True:
                request_line = f.readline(65536)
                if not request_line:
                    return
                if request_line in (b'\r\n', b'\n'):
                    continue
                try:
                    parts = request_line.decode('latin-1').strip().split(' ')
                    method, target, version = parts[0], parts[1], (parts[2] if len(parts) > 2 else 'HTTP/1.1')
                except Exception:
                    return
                headers = {}
                header_list = []
                while True:
                    line = f.readline(65536)
                    if line in (b'\r\n', b'\n', b''):
                        break
                    if b':' in line:
                        k, v = line.decode('latin-1').split(':', 1)
                        headers[k.strip().lower()] = v.strip(); header_list.append((k.strip().lower(), v.strip()))
                # body
                body = b''
                if 'content-length' in headers:
                    try: length = int(headers['content-length'])
                    except Exception: length = 0
                    if headers.get('expect', '').lower() == '100-continue':
                        conn.sendall(b'HTTP/1.1 100 Continue\r\n\r\n')
                    if length > 0:
                        body = f.read(length)
                elif headers.get('transfer-encoding', '').lower() == 'chunked':
                    if headers.get('expect', '').lower() == '100-continue':
                        conn.sendall(b'HTTP/1.1 100 Continue\r\n\r\n')
                    chunks = []
                    while True:
                        size_line = f.readline(65536).strip()
                        try: size = int(size_line.split(b';')[0], 16)
                        except Exception: size = 0
                        if size == 0:
                            # consume trailers until blank
                            while True:
                                tl = f.readline(65536)
                                if tl in (b'\r\n', b'\n', b''): break
                            break
                        chunks.append(f.read(size)); f.readline(65536)
                    body = b''.join(chunks)
                # route
                raw_target = target
                if raw_target.startswith('http://') or raw_target.startswith('https://'):
                    # absolute-form
                    rest = raw_target.split('://', 1)[1]
                    slash = rest.find('/')
                    raw_target = rest[slash:] if slash >= 0 else '/'
                if '?' in raw_target:
                    raw_path, query = raw_target.split('?', 1)
                else:
                    raw_path, query = raw_target, ''
                try:
                    resp = self.route(method, raw_path, query, body, headers)
                except Exception:
                    resp = _Response(500, [('content-type', 'text/plain; charset=utf-8')], b'Internal Server Error')
                close_after = False
                conn_hdr = headers.get('connection', '').lower()
                if version == 'HTTP/1.0' and 'keep-alive' not in conn_hdr:
                    close_after = True
                if 'close' in conn_hdr:
                    close_after = True
                if resp.shutdown:
                    close_after = True
                out_headers = list(resp.headers)
                body_out = b'' if method == 'HEAD' else resp.body
                out_headers.append(('content-length', str(len(resp.body))))
                if close_after:
                    out_headers.append(('connection', 'close'))
                out_headers.append(('date', formatdate(time.time(), usegmt=True)))
                status_line = 'HTTP/1.1 %d %s\r\n' % (resp.status, _STATUS_REASONS.get(resp.status, ''))
                head_bytes = status_line.encode('latin-1')
                for k, v in out_headers:
                    head_bytes += ('%s: %s\r\n' % (k, v)).encode('latin-1', 'replace')
                head_bytes += b'\r\n'
                try:
                    conn.sendall(head_bytes + body_out)
                except OSError:
                    return
                if resp.shutdown:
                    self.shutdown_requested = True
                    try: self.listener.close()
                    except Exception: pass
                    return
                if close_after:
                    return
        except Exception:
            return
        finally:
            try: conn.close()
            except Exception: pass


def _form_decode(s):
    # url form decoding: '+' -> space, percent decode with replacement chars
    s = s.replace('+', ' ')
    return unquote(s, encoding='utf-8', errors='replace')

def open_browser_if(cfg):
    if not cfg.get('open_browser'):
        return
    if cfg.get('port') == 0:
        return
    url = 'http://%s:%d/' % (cfg['host'], cfg['port'])
    xdg = shutil.which('xdg-open')
    if xdg:
        try:
            subprocess.Popen([xdg, url], stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
        except Exception:
            pass
